import subprocess, os

def handle(query, state):
    filename = (query.get("filename") or [""])[0]
    if not filename:
        return 200, {"Content-Type": "text/plain"}, "Usage: ?filename=<name>"
    env = dict(os.environ)
    env["SECRET_FLAG"] = state["flag"]
    try:
        result = subprocess.run(
            f"ls -la {filename}",
            shell=True,
            capture_output=True,
            text=True,
            env=env,
            timeout=5
        )
        output = result.stdout + result.stderr
        return 200, {"Content-Type": "text/plain"}, output
    except subprocess.TimeoutExpired:
        return 500, {"Content-Type": "text/plain"}, "Timeout"
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, str(e)
